select private.release_mysteries('e2e-73aa85206bfa', 'e2e', '[{"id":"fx.m.film.0101","category":"film","answer_type":"film","answer_entity":"fx.x.film.the-lantern-keeper-1987","accepted_entities":[],"clues":["Its title names the job of whoever tends the lamp at the top of a lighthouse.","Its hero tends a light on a sea rock for thirty winters with a grey cat.","This fixture film won the Gold Gull prize in 1988, the year after it came out.","One word of its title names the glass room that holds a lighthouse''s lamp."],"distractors":["fx.x.film.the-tide-clock-1985","fx.x.film.the-last-ferryman-1977","fx.x.film.night-ferry-to-pellin-1968"],"slot":1,"explanation":"The top of a lighthouse is its lantern, and the one who tends it is the keeper. The film''s watchman and his grey cat won the Gold Gull a year after its release.","learn_more":"The Lantern Keeper (fixture film)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.geo.0101","category":"geo","answer_type":"country","answer_entity":"fx.x.country.arvenna","accepted_entities":[],"clues":["Swap the two letters at the front of the black bird on its banners, and you have the start of its name.","Unlike the kingdoms around it, it elects a president.","Its name begins and ends with the letter A.","This fixture country''s name starts with A and has a double N in the middle."],"distractors":["fx.x.country.belloria","fx.x.country.cassova","fx.x.country.dravenor"],"slot":3,"explanation":"Swap the R and A of the raven on its banners and you get Arven, as in the Arven Republic, which elects a president. Its name starts and ends with A.","learn_more":"Arvenna (fixture)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.geo.0102","category":"geo","answer_type":"country","answer_entity":"fx.x.country.valdoria","accepted_entities":[],"clues":["Its parliament meets once a year on a barge moored in a mountain lake.","Its national dish is a stew of smoked eel and juniper.","It shares a long border with fixture Arvenna along the Ashen Hills.","This fixture country flies a white mountain on a green field."],"distractors":["fx.x.country.ostravia","fx.x.country.pellinor","fx.x.country.rosmaar"],"slot":2,"explanation":"The mountain country north of the Ashen Hills holds its parliament on a lake barge, and smoked eel stew is its national dish.","learn_more":"Valdoria (fixture)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.hist.0101","category":"hist","answer_type":"person","answer_entity":"fx.x.person.odile-marsh","accepted_entities":[],"clues":["The fixture Cindral archive holds nineteen leather volumes of this person''s survey notes.","She walked a whole river from source to sea with a brass chain and a compass.","Harbour pilots steered by her coastal charts for a hundred years.","This fixture mapmaker drew the coastline of Arvenna in 1831."],"distractors":["fx.x.person.liesl-varo","fx.x.person.ennis-ward","fx.x.person.mira-tolland"],"slot":1,"explanation":"The surveyor who chained a river from source to sea went on to chart the whole coast for the harbour pilots.","learn_more":"Odile Marsh (fixture)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.sci.0101","category":"sci","answer_type":"element","answer_entity":"fx.x.element.cobalt","accepted_entities":[],"clues":["The glassblowers of fixture Halvessa stir a pinch of it into molten glass.","Its salts colour the deep blue tiles of the fixture Cindral baths.","It sits between iron and nickel in the periodic table.","This element''s symbol is Co, and its atomic number is 27."],"distractors":["fx.x.element.copper","fx.x.element.nickel","fx.x.element.iron"],"slot":2,"explanation":"Cobalt salts give glass and tiles a deep blue, which is why Halvessa glassblowers and the Cindral bath builders both used it.","learn_more":"Cobalt","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.sci.0102","category":"sci","answer_type":"element","answer_entity":"fx.x.element.bismuth","accepted_entities":[],"clues":["Long counted the heaviest stable element, it was found in 2003 to decay, with a half-life over a billion times the age of the universe.","Like water, it expands as it freezes.","Its crystals grow in stepped squares with a rainbow sheen.","This element''s symbol is Bi, and its atomic number is 83."],"distractors":["fx.x.element.antimony","fx.x.element.lead","fx.x.element.tin"],"slot":3,"explanation":"Bismuth-209 decays so slowly that it passed for stable until 2003. Like water it expands as it freezes, and its crystals grow in rainbow-tinted steps.","learn_more":"Bismuth","source_labels":[],"review_by":null,"status":"active"}]'::jsonb);

